package com.demonslayer;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class KillAttributionTest
{
	@Test
	public void requiresRecentLocalHitAndDeduplicatesDeath()
	{
		KillAttribution tracker = new KillAttribution();
		tracker.spawn(1);
		assertFalse(tracker.death(1, 1));
		tracker.spawn(2);
		tracker.localHit(2, 2);
		assertTrue(tracker.death(2, 5));
		assertFalse(tracker.death(2, 5));
		tracker.spawn(3);
		tracker.localHit(3, 2);
		assertFalse(tracker.death(3, 20));
		tracker.spawn(4);
		tracker.localHit(4, 5);
		tracker.clear();
		assertFalse(tracker.death(4, 6));
	}
}

package com.demonslayer;

import static org.junit.Assert.assertEquals;
import com.google.gson.Gson;
import java.io.StringReader;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class BossSyncTest
{
	private final MonsterCatalog catalog = MonsterCatalog.parse(new Gson(), new StringReader(
		"{\"npcs\":{\"8061\":{\"name\":\"Vorkath\",\"page\":\"Vorkath\",\"level\":732,\"attributes\":[\"undead\"],\"boss\":true}}}"));
	private final BossSync sync = new BossSync(catalog);

	@Test
	public void repeatedLowerAndMissingSyncs()
	{
		Progression.Profile profile = new Progression.Profile();
		assertEquals(5, sync.importKnown(profile, Collections.singletonMap("Vorkath", 5)).importedKills);
		assertEquals(5 * 732, Progression.xp(profile));
		assertEquals(0, sync.importKnown(profile, Collections.singletonMap("Vorkath", 5)).importedKills);
		assertEquals(0, sync.importKnown(profile, Collections.singletonMap("Vorkath", 3)).importedKills);
		assertEquals(2, sync.importKnown(profile, Collections.singletonMap("Vorkath", 7)).importedKills);
		assertEquals(7, Progression.kills(profile.bossRecords));
	}

	@Test
	public void liveThenSyncAndSyncThenDeath()
	{
		Progression.Profile profile = new Progression.Profile();
		MonsterCatalog.Monster vorkath = catalog.byId(8061);
		sync.importKnown(profile, Collections.singletonMap("Vorkath", 5));
		assertEquals(732, sync.liveKill(profile, vorkath, 5, 6, 732));
		assertEquals(0, sync.importKnown(profile, Collections.singletonMap("Vorkath", 6)).importedKills);
		assertEquals(1, sync.importKnown(profile, Collections.singletonMap("Vorkath", 7)).importedKills);
		assertEquals(0, sync.liveKill(profile, vorkath, 6, 7, 732));
		assertEquals(7, Progression.kills(profile.bossRecords));
	}

	@Test
	public void unresolvedNameDoesNotAward()
	{
		Progression.Profile profile = new Progression.Profile();
		BossSync.Result result = sync.importKnown(profile, Collections.singletonMap("Unknown", 100));
		assertEquals(0, result.importedKills);
		assertEquals(1, result.unresolved.size());
		assertEquals(0, Progression.xp(profile));
	}

	@Test
	public void knownIneligibleKcNamesAreIgnoredButUnknownNamesRemainVisible()
	{
		BossSync bundledSync = new BossSync(MonsterCatalog.load(new Gson()));
		Progression.Profile profile = new Progression.Profile();
		Map<String, Integer> known = new HashMap<>();
		for (String name : new String[]{"gauntlet", "guardians of the rift", "lunar chest",
			"mimic", "royal titans"})
		{
			known.put(name, 100);
		}
		known.put("Unknown future boss", 100);
		known.put("Vorkath", 2);
		BossSync.Result result = bundledSync.importKnown(profile, known);
		assertEquals(2, result.importedKills);
		assertEquals(784, result.awardedXp);
		assertEquals(Collections.singletonList("Unknown future boss"), result.unresolved);
		assertEquals(2, Progression.kills(profile.bossRecords));
	}
}

package com.demonslayer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.client.ui.overlay.OverlayPosition;
import org.junit.Test;

public class DemonSlayerCrowOverlayTest
{
	@Test
	public void refreshNoticeRendersAwayFromMinimapAndExpires()
	{
		AtomicInteger tick = new AtomicInteger(100);
		AtomicBoolean loggedIn = new AtomicBoolean(true);
		DemonSlayerCrowOverlay overlay = new DemonSlayerCrowOverlay(tick::get, loggedIn::get);
		BufferedImage frame = new BufferedImage(234, 58, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = frame.createGraphics();
		try
		{
			assertEquals(OverlayPosition.TOP_CENTER, overlay.getPosition());
			assertNull(overlay.render(graphics));
			overlay.show("Boss records refreshed.");
			assertNotNull(overlay.render(graphics));
			assertTrue((frame.getRGB(15, 15) >>> 24) != 0);
			loggedIn.set(false);
			assertNull(overlay.render(graphics));
			loggedIn.set(true);
			tick.set(112);
			assertNotNull(overlay.render(graphics));
			tick.set(113);
			assertNull(overlay.render(graphics));
		}
		finally
		{
			graphics.dispose();
		}
	}
}

package com.demonslayer;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import org.junit.Test;

public class DemonSlayerPanelLayoutTest
{
	@Test
	public void tabsFitStandardSidebarAtKinotoAndHashira() throws Exception
	{
		DemonSlayerPanel[] panels = new DemonSlayerPanel[1];
		Progression.Profile profile = new Progression.Profile();
		Progression.Record record = new Progression.Record("Vorkath", false, true, 392);
		record.kills = 5_509;
		record.xp = 2_159_528;
		profile.bossRecords.put("vorkath", record);
		Progression.Record longName = new Progression.Record("Tormented demon (elite variant)", true, false, 450);
		longName.kills = 1;
		profile.normalRecords.put("123", longName);
		SwingUtilities.invokeAndWait(() ->
		{
			panels[0] = new DemonSlayerPanel(() -> { }, new DemonSlayerConfig() { });
			panels[0].setSize(225, 620);
			panels[0].update(profile, "Lara The Ant", "0 historical kills; 0 XP. 5 names unresolved.",
				"Boss records synchronized.", java.util.Arrays.asList("gauntlet", "guardians of the rift",
					"lunar chest", "mimic", "royal titans"));
		});
		SwingUtilities.invokeAndWait(() ->
		{
			DemonSlayerPanel panel = panels[0];
			panel.doLayout();
			JScrollPane scroll = (JScrollPane) panel.getComponent(1);
			scroll.doLayout();
			assertFits(scroll, "Profile");
			JPanel top = (JPanel) panel.getComponent(0);
			JPanel tabs = (JPanel) top.getComponent(1);
			((JButton) tabs.getComponent(1)).doClick();
			scroll.doLayout();
			assertFits(scroll, "Records");
			((JButton) tabs.getComponent(2)).doClick();
			scroll.doLayout();
			assertFits(scroll, "Rewards");
		});
		record.xp = 200_000_000;
		record.kills = 10_000;
		SwingUtilities.invokeAndWait(() -> panels[0].update(profile, "Lara The Ant", null,
			"Hashira mastery milestone.", java.util.Collections.emptyList()));
		SwingUtilities.invokeAndWait(() ->
		{
			DemonSlayerPanel panel = panels[0];
			JPanel tabs = (JPanel) ((JPanel) panel.getComponent(0)).getComponent(1);
			((JButton) tabs.getComponent(0)).doClick();
			JScrollPane scroll = (JScrollPane) panel.getComponent(1);
			scroll.doLayout();
			assertFits(scroll, "Hashira Profile");
			((JButton) tabs.getComponent(2)).doClick();
			scroll.doLayout();
			assertFits(scroll, "Hashira Rewards");
		});
	}

	private static void assertFits(JScrollPane scroll, String tab)
	{
		int contentWidth = scroll.getViewport().getView().getPreferredSize().width;
		int viewportWidth = scroll.getViewport().getExtentSize().width;
		assertTrue(tab + " content width " + contentWidth + " > viewport " + viewportWidth,
			contentWidth <= viewportWidth);
		assertFalse(tab + " horizontal scrollbar", scroll.getHorizontalScrollBar().isVisible());
		assertFalse(tab + " vertical scrollbar", scroll.getVerticalScrollBar().isVisible());
	}
}

