package com.demonslayer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class ProfileStoreTest
{
	private static final class MemoryBackend implements ProfileStore.Backend
	{
		String active;
		final Map<String, String> values = new HashMap<>();

		@Override public String profileKey() { return active; }
		@Override public String read(String group, String key) { return values.get(active + group + key); }
		@Override public void write(String group, String key, String value) { values.put(active + group + key, value); }
	}

	@Test
	public void isolatesAndReloadsProfiles()
	{
		MemoryBackend backend = new MemoryBackend();
		ProfileStore store = new ProfileStore(new Gson(), backend);
		assertNull(store.loadActive());
		backend.active = "account-a";
		Progression.Profile first = store.loadActive();
		Progression.Record record = new Progression.Record("Demon", true, false, 12);
		first.normalRecords.put("1", record);
		Progression.award(first, record, 1, 12);
		store.saveActive();
		backend.active = "account-b";
		assertEquals(0, Progression.kills(store.loadActive()));
		store.clear();
		backend.active = "account-a";
		assertEquals(1, Progression.kills(store.loadActive()));
		assertEquals(12, Progression.xp(store.loadActive()));
	}

	@Test(expected = JsonParseException.class)
	public void refusesCorruptProfileWithoutReplacingIt()
	{
		MemoryBackend backend = new MemoryBackend();
		backend.active = "account-a";
		backend.values.put("account-a" + ProfileStore.GROUP + "profile-v1", "{\"version\":99}");
		ProfileStore store = new ProfileStore(new Gson(), backend);
		try
		{
			store.loadActive();
		}
		finally
		{
			assertEquals("{\"version\":99}", backend.values.get("account-a"
				+ ProfileStore.GROUP + "profile-v1"));
		}
	}
}

package com.demonslayer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.StringReader;
import org.junit.Test;

public class ProgressionTest
{
	@Test
	public void levelsAndCap()
	{
		Progression.Profile profile = new Progression.Profile();
		Progression.Record record = new Progression.Record("Demon", true, false, 100);
		profile.normalRecords.put("1", record);
		assertEquals(1, Progression.level(profile));
		Progression.award(profile, record, 1, 83);
		assertEquals(2, Progression.level(profile));
		Progression.award(profile, record, 2_000_000, 100);
		assertEquals(99, Progression.level(profile));
		assertEquals(200_000_000, Progression.xp(profile));
		assertEquals(2_000_001, record.kills);
		assertEquals(200_000_000 - Progression.HASHIRA_XP, Progression.mastery(profile));
	}

	@Test
	public void ranksAndDualAttributes()
	{
		assertEquals("Mizunoto", Progression.RANKS[Progression.rankIndex(1)]);
		assertEquals("Hinoe", Progression.RANKS[Progression.rankIndex(74)]);
		assertEquals("Hashira", Progression.RANKS[Progression.rankIndex(99)]);
		Progression.Profile profile = new Progression.Profile();
		Progression.Record record = new Progression.Record("Both", true, true, 20);
		profile.normalRecords.put("42", record);
		Progression.award(profile, record, 1, 20);
		assertEquals(1, Progression.kills(profile));
		assertEquals(1, Progression.categoryKills(profile, true));
		assertEquals(1, Progression.categoryKills(profile, false));
		assertEquals(20, Progression.xp(profile));
		Progression.Profile display = Progression.snapshot(profile);
		Progression.award(profile, record, 1, 20);
		assertEquals(1, Progression.kills(display));
		assertEquals(2, Progression.kills(profile));
	}

	@Test
	public void masteryAndBossRewardTiersFollowTheirThresholds()
	{
		Progression.Profile profile = new Progression.Profile();
		Progression.Record normal = new Progression.Record("Demon", true, false, 100);
		Progression.Record boss = new Progression.Record("Boss", true, false, 100);
		profile.normalRecords.put("1", normal);
		profile.bossRecords.put("boss", boss);
		assertEquals(0, Progression.masteryTier(profile));
		assertEquals(0, Progression.bossTier(profile));
		Progression.award(profile, normal, 200_000, 100);
		assertEquals(1, Progression.masteryTier(profile));
		Progression.award(profile, boss, 100, 100);
		assertEquals(1, Progression.bossTier(profile));
		Progression.award(profile, normal, 1_800_000, 100);
		assertEquals(4, Progression.masteryTier(profile));
	}

	@Test
	public void parsesAndResolvesLowestEligibleBoss()
	{
		String json = "{\"npcs\":{\"1\":{\"name\":\"Vorkath\",\"page\":\"Vorkath\",\"level\":732,\"attributes\":[\"undead\"],\"boss\":true},"
			+ "\"2\":{\"name\":\"Vorkath\",\"page\":\"Vorkath\",\"level\":600,\"attributes\":[\"undead\"],\"boss\":true}}}";
		MonsterCatalog catalog = MonsterCatalog.parse(new Gson(), new StringReader(json));
		assertEquals(2, catalog.size());
		assertEquals(600, catalog.bossByName("Vorkath").level);
		assertEquals(732, catalog.byId(1).level);
	}

	@Test
	public void bundledWikiCatalogLoadsAndResolvesEligibleVariants()
	{
		MonsterCatalog catalog = MonsterCatalog.load(new Gson());
		assertTrue(catalog.size() > 500);
		assertNotNull(catalog.byId(8061));
		assertEquals(392, catalog.bossByName("Vorkath").level);
		assertEquals(732, catalog.byId(8061).level);
	}

	@Test(expected = JsonParseException.class)
	public void rejectsInvalidCatalogRow()
	{
		MonsterCatalog.parse(new Gson(), new StringReader("{\"npcs\":{\"oops\":{\"name\":\"X\"}}}"));
	}
}

package com.demonslayer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class DemonSlayerOverlay extends Overlay
{
	private static final Color GOLD = new Color(214, 174, 100);
	private static final int OVERHEAD_NAME_OFFSET = 40;
	private static final int TITLE_NAME_GAP = 5;

	private final Client client;
	private final DemonSlayerConfig config;
	private String cachedTitle;

	DemonSlayerOverlay(Client client, DemonSlayerConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	void setProfile(Progression.Profile profile)
	{
		int level = profile == null ? 0 : Progression.level(profile);
		cachedTitle = level < 50 ? null : level == 99 ? "柱  HASHIRA"
			: level >= 90 ? "◆  KINOE  ◆"
			: Progression.RANKS[Progression.rankIndex(level)].toUpperCase();
	}

	void clear()
	{
		cachedTitle = null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		if (cachedTitle != null && config.localTitle())
		{
			drawTitle(graphics);
		}
		return null;
	}

	private void drawTitle(Graphics2D graphics)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		String title = cachedTitle;
		graphics.setFont(new Font("Dialog", Font.BOLD, 12));
		Point position = player.getCanvasTextLocation(graphics, title,
			player.getLogicalHeight() + OVERHEAD_NAME_OFFSET);
		if (position == null)
		{
			return;
		}
		// Player Indicators uses this same anchor for overhead names. Draw one text line below it.
		int y = position.getY() + graphics.getFontMetrics().getHeight() + TITLE_NAME_GAP;
		graphics.setColor(Color.BLACK);
		graphics.drawString(title, position.getX() + 1, y + 1);
		graphics.setColor(GOLD);
		graphics.drawString(title, position.getX(), y);
	}

}

package com.demonslayer;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

final class MonsterCatalog
{
	static final String RESOURCE = "/com/demonslayer/monsters.json";

	static final class Monster
	{
		String name;
		String page;
		int level;
		String[] attributes;
		boolean boss;

		boolean demon()
		{
			return hasAttribute("demon");
		}

		boolean undead()
		{
			return hasAttribute("undead");
		}

		private boolean hasAttribute(String expected)
		{
			if (attributes != null)
			{
				for (String attribute : attributes)
				{
					if (expected.equals(attribute))
					{
						return true;
					}
				}
			}
			return false;
		}
	}

	private static final class Document
	{
		String source;
		Map<String, Monster> npcs;
		List<String> excludedBossNames;
		List<String> excludedKcNames;
	}

	private final Map<Integer, Monster> byId;
	private final Map<String, Monster> bossesByName;
	private final Set<String> excludedKcNames;

	private MonsterCatalog(Map<Integer, Monster> byId, Map<String, Monster> bossesByName,
		Set<String> excludedKcNames)
	{
		this.byId = Collections.unmodifiableMap(byId);
		this.bossesByName = Collections.unmodifiableMap(bossesByName);
		this.excludedKcNames = Collections.unmodifiableSet(excludedKcNames);
	}

	static MonsterCatalog load(Gson gson)
	{
		InputStream stream = MonsterCatalog.class.getResourceAsStream(RESOURCE);
		if (stream == null)
		{
			throw new IllegalStateException("Missing bundled monster catalog");
		}
		try (InputStreamReader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
		{
			return parse(gson, reader);
		}
		catch (java.io.IOException e)
		{
			throw new IllegalStateException("Unable to read bundled monster catalog", e);
		}
	}

	static MonsterCatalog parse(Gson gson, java.io.Reader reader)
	{
		Document document = gson.fromJson(reader, Document.class);
		if (document == null || document.npcs == null || document.npcs.isEmpty())
		{
			throw new JsonParseException("Monster catalog is empty");
		}
		Map<Integer, Monster> ids = new HashMap<>();
		Map<String, Monster> bosses = new HashMap<>();
		for (Map.Entry<String, Monster> row : document.npcs.entrySet())
		{
			Monster monster = row.getValue();
			int id;
			try
			{
				id = Integer.parseInt(row.getKey());
			}
			catch (NumberFormatException e)
			{
				throw new JsonParseException("Invalid NPC ID " + row.getKey(), e);
			}
			if (id <= 0 || monster == null || monster.name == null || monster.page == null
				|| monster.level <= 0 || (!monster.demon() && !monster.undead()))
			{
				throw new JsonParseException("Invalid monster catalog row " + row.getKey());
			}
			ids.put(id, monster);
			if (monster.boss)
			{
				addBoss(bosses, monster.name, monster);
				addBoss(bosses, monster.page, monster);
			}
		}
		Set<String> excluded = new HashSet<>();
		if (document.excludedBossNames != null)
		{
			for (String name : document.excludedBossNames)
			{
				if (name != null)
				{
					excluded.add(normalize(name));
				}
			}
		}
		if (document.excludedKcNames != null)
		{
			for (String name : document.excludedKcNames)
			{
				if (name != null)
				{
					excluded.add(normalize(name));
				}
			}
		}
		return new MonsterCatalog(ids, bosses, excluded);
	}

	private static void addBoss(Map<String, Monster> bosses, String name, Monster monster)
	{
		String key = normalize(name);
		Monster previous = bosses.get(key);
		if (previous == null || monster.level < previous.level
			|| (monster.level == previous.level && monster.page.compareTo(previous.page) < 0))
		{
			bosses.put(key, monster);
		}
	}

	static String normalize(String value)
	{
		return value.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	Monster byId(int id)
	{
		return byId.get(id);
	}

	Monster bossByName(String name)
	{
		return bossesByName.get(normalize(name));
	}

	boolean isExcludedKc(String name)
	{
		return excludedKcNames.contains(normalize(name));
	}

	int size()
	{
		return byId.size();
	}
}

package com.demonslayer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.function.BooleanSupplier;
import java.util.function.IntSupplier;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

/** Brief Corps notices in RuneLite's managed top-center overlay area. */
final class DemonSlayerCrowOverlay extends Overlay
{
	private static final int WIDTH = 234;
	private static final int HEIGHT = 58;
	private static final int VISIBLE_TICKS = 12;
	private static final Color INK = new Color(23, 20, 22, 232);
	private static final Color GOLD = new Color(214, 174, 100);
	private static final Color TEXT = new Color(238, 226, 208);
	private static final BufferedImage CROW = ImageUtil.loadImageResource(DemonSlayerCrowOverlay.class,
		"crow.png");

	private final IntSupplier tick;
	private final BooleanSupplier loggedIn;
	private String message;
	private int expiresAtTick;

	DemonSlayerCrowOverlay(IntSupplier tick, BooleanSupplier loggedIn)
	{
		this.tick = tick;
		this.loggedIn = loggedIn;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_LOW);
		setMovable(true);
		setSnappable(true);
	}

	void show(String text)
	{
		message = text;
		expiresAtTick = tick.getAsInt() + VISIBLE_TICKS;
	}

	void clear()
	{
		message = null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!loggedIn.getAsBoolean() || message == null || tick.getAsInt() > expiresAtTick)
		{
			return null;
		}
		Graphics2D g = (Graphics2D) graphics.create();
		g.setColor(INK);
		g.fillRoundRect(0, 0, WIDTH, HEIGHT, 10, 10);
		g.setColor(GOLD);
		g.drawRoundRect(0, 0, WIDTH - 1, HEIGHT - 1, 10, 10);
		g.drawImage(CROW, 8, 7, 43, 43, null);
		g.setFont(new Font("Dialog", Font.BOLD, 10));
		g.drawString("KASUGAI CROW  •  CORPS", 58, 21);
		g.setFont(new Font("Dialog", Font.PLAIN, 11));
		g.setColor(TEXT);
		g.drawString(fit(message, g.getFontMetrics(), WIDTH - 67), 58, 42);
		g.dispose();
		return new Dimension(WIDTH, HEIGHT);
	}

	private static String fit(String text, FontMetrics metrics, int maxWidth)
	{
		if (metrics.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		String ellipsis = "…";
		int end = text.length();
		while (end > 0 && metrics.stringWidth(text.substring(0, end) + ellipsis) > maxWidth)
		{
			end--;
		}
		return text.substring(0, end) + ellipsis;
	}
}

package com.demonslayer;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import net.runelite.client.config.ConfigManager;

final class ProfileStore
{
	static final String GROUP = "demon-slayer-progression";
	private static final String KEY = "profile-v1";

	interface Backend
	{
		String profileKey();
		String read(String group, String key);
		void write(String group, String key, String value);
	}

	static Backend runelite(ConfigManager configManager)
	{
		return new Backend()
		{
			@Override
			public String profileKey()
			{
				return configManager.getRSProfileKey();
			}

			@Override
			public String read(String group, String key)
			{
				return configManager.getRSProfileConfiguration(group, key);
			}

			@Override
			public void write(String group, String key, String value)
			{
				configManager.setRSProfileConfiguration(group, key, value);
			}
		};
	}

	private final Gson gson;
	private final Backend backend;
	private String activeKey;
	private Progression.Profile active;

	ProfileStore(Gson gson, Backend backend)
	{
		this.gson = gson;
		this.backend = backend;
	}

	Progression.Profile loadActive()
	{
		String key = backend.profileKey();
		if (key == null)
		{
			activeKey = null;
			active = null;
			return null;
		}
		if (key.equals(activeKey) && active != null)
		{
			return active;
		}
		String json = backend.read(GROUP, KEY);
		Progression.Profile parsed = json == null ? new Progression.Profile()
			: gson.fromJson(json, Progression.Profile.class);
		if (parsed == null || parsed.version != 1 || parsed.normalRecords == null || parsed.bossRecords == null)
		{
			throw new JsonParseException("Unsupported or malformed Demon Slayer profile");
		}
		validate(parsed.normalRecords);
		validate(parsed.bossRecords);
		if (Progression.xp(parsed) > Progression.MAX_XP)
		{
			throw new JsonParseException("Demon Slayer profile exceeds XP cap");
		}
		activeKey = key;
		active = parsed;
		return active;
	}

	private static void validate(java.util.Map<String, Progression.Record> records)
	{
		for (java.util.Map.Entry<String, Progression.Record> entry : records.entrySet())
		{
			Progression.Record record = entry.getValue();
			if (entry.getKey() == null || record == null || record.name == null || record.level <= 0
				|| record.kills < 0 || record.xp < 0 || (!record.demon && !record.undead))
			{
				throw new JsonParseException("Malformed Demon Slayer record " + entry.getKey());
			}
		}
	}

	void saveActive()
	{
		if (active == null || activeKey == null || !activeKey.equals(backend.profileKey()))
		{
			throw new IllegalStateException("No active RuneScape profile to save");
		}
		backend.write(GROUP, KEY, gson.toJson(active));
	}

	void clear()
	{
		activeKey = null;
		active = null;
	}
}

package com.demonslayer;

import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Experience;

final class Progression
{
	static final int MAX_XP = Experience.MAX_SKILL_XP;
	static final int HASHIRA_XP = Experience.getXpForLevel(99);
	static final long[] MASTERY_MILESTONES = {20_000_000L, 50_000_000L, 100_000_000L, 200_000_000L};
	static final long[] BOSS_MILESTONES = {100, 500, 1_000, 2_500, 5_000, 10_000};
	static final long[] TOTAL_MILESTONES = {100, 500, 1_000, 5_000, 10_000};
	static final String[] RANKS = {"Mizunoto", "Mizunoe", "Kanoto", "Kanoe", "Tsuchinoto",
		"Tsuchinoe", "Hinoto", "Hinoe", "Kinoto", "Kinoe", "Hashira"};
	static final int[] RANK_LEVELS = {1, 10, 20, 30, 40, 50, 60, 70, 80, 90, 99};

	static final class Record
	{
		String name;
		boolean demon;
		boolean undead;
		int level;
		long kills;
		long xp;

		Record(String name, boolean demon, boolean undead, int level)
		{
			this.name = name;
			this.demon = demon;
			this.undead = undead;
			this.level = level;
		}
	}

	static final class Profile
	{
		int version = 1;
		Map<String, Record> normalRecords = new LinkedHashMap<>();
		Map<String, Record> bossRecords = new LinkedHashMap<>();
		long lastBossSync;
	}

	private Progression()
	{
	}

	static long xp(Profile profile)
	{
		return xp(profile.normalRecords) + xp(profile.bossRecords);
	}

	static long xp(Map<String, Record> records)
	{
		long result = 0;
		for (Record record : records.values())
		{
			result += record.xp;
		}
		return result;
	}

	static long kills(Map<String, Record> records)
	{
		long result = 0;
		for (Record record : records.values())
		{
			result += record.kills;
		}
		return result;
	}

	static long kills(Profile profile)
	{
		return kills(profile.normalRecords) + kills(profile.bossRecords);
	}

	static long categoryKills(Profile profile, boolean demon)
	{
		return categoryKills(profile.normalRecords, demon) + categoryKills(profile.bossRecords, demon);
	}

	private static long categoryKills(Map<String, Record> records, boolean demon)
	{
		long result = 0;
		for (Record record : records.values())
		{
			if (demon ? record.demon : record.undead)
			{
				result += record.kills;
			}
		}
		return result;
	}

	static int level(Profile profile)
	{
		return Math.min(99, Experience.getLevelForXp((int) Math.min(xp(profile), MAX_XP)));
	}

	static int rankIndex(int level)
	{
		for (int i = RANK_LEVELS.length - 1; i >= 0; i--)
		{
			if (level >= RANK_LEVELS[i])
			{
				return i;
			}
		}
		return 0;
	}

	static long mastery(Profile profile)
	{
		return Math.max(0, xp(profile) - HASHIRA_XP);
	}

	static int masteryTier(Profile profile)
	{
		return tier(xp(profile), MASTERY_MILESTONES);
	}

	static int bossTier(Profile profile)
	{
		return tier(kills(profile.bossRecords), BOSS_MILESTONES);
	}

	private static int tier(long progress, long[] milestones)
	{
		int result = 0;
		for (long milestone : milestones)
		{
			if (progress >= milestone)
			{
				result++;
			}
		}
		return result;
	}

	static long award(Profile profile, Record record, long kills, int xpPerKill)
	{
		if (kills <= 0 || xpPerKill <= 0)
		{
			return 0;
		}
		long remaining = Math.max(0, MAX_XP - xp(profile));
		long earned = Math.min(remaining, kills * (long) xpPerKill);
		record.kills += kills;
		record.xp += earned;
		return earned;
	}

	static Record getOrCreate(Map<String, Record> records, String key, MonsterCatalog.Monster monster)
	{
		return records.computeIfAbsent(key,
			ignored -> new Record(monster.name, monster.demon(), monster.undead(), monster.level));
	}

	/** Keep Swing rendering on a stable copy while the client thread records kills. */
	static Profile snapshot(Profile source)
	{
		if (source == null)
		{
			return null;
		}
		Profile copy = new Profile();
		copy.lastBossSync = source.lastBossSync;
		copyRecords(source.normalRecords, copy.normalRecords);
		copyRecords(source.bossRecords, copy.bossRecords);
		return copy;
	}

	private static void copyRecords(Map<String, Record> from, Map<String, Record> to)
	{
		for (Map.Entry<String, Record> entry : from.entrySet())
		{
			Record original = entry.getValue();
			Record record = new Record(original.name, original.demon, original.undead, original.level);
			record.kills = original.kills;
			record.xp = original.xp;
			to.put(entry.getKey(), record);
		}
	}
}

