	DemonSlayerPanel(Runnable onSync, DemonSlayerConfig config)
	{
		this.onSync = onSync;
		this.config = config;
		setLayout(new BorderLayout());
		setBackground(INK);
		JPanel top = new JPanel(new BorderLayout());
		top.setBackground(INK);
